SELECT
    cast(`key` AS STRING) AS externalId
  , CASE WHEN coalesce(trim(`parentExternalId`), '') = '' THEN NULL ELSE node_reference(trim(`parentSpace`), trim(`parentExternalId`)) END AS `parent`
  , cast(`description` AS STRING) AS `description`
  , cast(`name` AS STRING) AS `name`
  , cast(`sourceContext` AS STRING) AS `sourceContext`
  , cast(`sourceId` AS STRING) AS `sourceId`
FROM `{{energyBaseRawDb}}`.`EnergyAsset`
